package at.prem.tiguantankplanner;

import android.Manifest; import android.app.Activity; import android.content.Intent; import android.content.pm.PackageManager; import android.location.Location; import android.location.LocationManager; import android.net.Uri; import android.os.Bundle; import android.provider.Settings; import android.widget.*; import org.json.*; import java.io.*; import java.net.*; import java.util.*;

public class MainActivity extends Activity {
 private static final int REQ_LOCATION=42; private static final String HOME="Aggsbach Markt, Österreich"; private static final double HOME_LAT=48.2946,HOME_LON=15.4037;
 private EditText destinationInput,rangeInput,consumptionInput; private TextView locationText,resultText; private Button mapsButton; private Location currentLocation; private Station bestStation;
 static class Point{double lat,lon,km;Point(double a,double o,double k){lat=a;lon=o;km=k;}} static class Station{String id,name,address;double lat,lon,price,routeKm,detourKm,totalCost;boolean beforeDestination;} static class RouteData{List<Point> points=new ArrayList<>();double totalKm,firstLegKm;}
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);int p=(int)(20*getResources().getDisplayMetrics().density);box.setPadding(p,p,p,p);scroll.addView(box);TextView title=new TextView(this);title.setText("Tiguan TankPlaner");title.setTextSize(28);box.addView(title);TextView sub=new TextView(this);sub.setText("Diesel • 6,0 l/100 km • Rückfahrt nach Aggsbach Markt");box.addView(sub);Button locate=new Button(this);locate.setText("📍 Standort ermitteln");box.addView(locate);locationText=new TextView(this);locationText.setText("Standort: noch nicht ermittelt");box.addView(locationText);destinationInput=new EditText(this);destinationInput.setHint("Ziel: Ort, Straße Hausnummer oder PLZ");box.addView(destinationInput);rangeInput=new EditText(this);rangeInput.setHint("Restreichweite laut Tiguan (km)");rangeInput.setInputType(2|8192);box.addView(rangeInput);consumptionInput=new EditText(this);consumptionInput.setHint("Verbrauch l/100 km");consumptionInput.setText("6.0");consumptionInput.setInputType(2|8192);box.addView(consumptionInput);Button calc=new Button(this);calc.setText("⛽ Wirtschaftlichste Tankstelle suchen");box.addView(calc);mapsButton=new Button(this);mapsButton.setText("🗺️ Route in Google Maps öffnen");mapsButton.setEnabled(false);box.addView(mapsButton);resultText=new TextView(this);resultText.setPadding(0,p,0,p);box.addView(resultText);setContentView(scroll);locate.setOnClickListener(v->getLocation());calc.setOnClickListener(v->startCalculation());mapsButton.setOnClickListener(v->openMaps());}
 private void getLocation(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},REQ_LOCATION);return;}LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);if(!lm.isProviderEnabled(LocationManager.GPS_PROVIDER)&&!lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER)){startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));return;}try{Location loc=lm.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(loc==null)loc=lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER);currentLocation=loc;if(loc!=null)locationText.setText(String.format(Locale.GERMANY,"Standort: %.5f, %.5f",loc.getLatitude(),loc.getLongitude()));else locationText.setText("GPS aktiv lassen und nochmals tippen.");}catch(SecurityException e){locationText.setText("Standortberechtigung fehlt.");}}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ_LOCATION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)getLocation();}
 private void startCalculation(){String dest=destinationInput.getText().toString().trim();if(currentLocation==null){Toast.makeText(this,"Bitte zuerst Standort ermitteln.",Toast.LENGTH_LONG).show();return;}if(dest.isEmpty()||rangeInput.getText().toString().trim().isEmpty()){Toast.makeText(this,"Ziel und Restreichweite eingeben.",Toast.LENGTH_LONG).show();return;}final double range,cons;try{range=Double.parseDouble(rangeInput.getText().toString().replace(',','.'));cons=Double.parseDouble(consumptionInput.getText().toString().replace(',','.'));}catch(Exception e){Toast.makeText(this,"Ungültige Zahlen.",Toast.LENGTH_LONG).show();return;}bestStation=null;mapsButton.setEnabled(false);resultText.setText("Suche Zieladresse …");new Thread(()->{try{double[] d=geocode(dest);RouteData rd=route(currentLocation.getLatitude(),currentLocation.getLongitude(),d[0],d[1],HOME_LAT,HOME_LON);double reserve=25.0,safeReach=Math.max(0,range-reserve),litersNeeded=Math.max(0,(rd.totalKm+reserve-range)*cons/100.0);if(litersNeeded<=0){runOnUiThread(()->{resultText.setText(String.format(Locale.GERMANY,"✅ Ziel gefunden. Rundfahrt ca. %.0f km.\nRestreichweite %.0f km + 25 km Reserve reichen aus.\n\nWirtschaftlichste Lösung: kein Tankstopp nötig.",rd.totalKm,range));mapsButton.setEnabled(true);});return;}Map<String,Station> all=new HashMap<>();int samples=Math.min(8,rd.points.size());for(int s=0;s<samples;s++){int idx=(int)Math.round(s*(rd.points.size()-1.0)/(samples-1.0));Point pnt=rd.points.get(idx);if(pnt.km>safeReach+20)continue;JSONArray arr=econtrol(pnt.lat,pnt.lon);for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null)continue;JSONArray prices=o.optJSONArray("prices");JSONObject loc=o.optJSONObject("location");if(prices==null||prices.length()==0||loc==null)continue;double slat=loc.optDouble("latitude",Double.NaN),slon=loc.optDouble("longitude",Double.NaN);JSONObject po=prices.optJSONObject(0);if(po==null)continue;double price=po.optDouble("amount",Double.NaN);if(Double.isNaN(slat)||Double.isNaN(slon)||Double.isNaN(price))continue;double air=haversine(pnt.lat,pnt.lon,slat,slon),detour=air*2.5;Station st=new Station();st.id=o.optString("id",o.optString("name","")+slat+slon);st.name=o.optString("name","Tankstelle");st.address=address(loc);st.lat=slat;st.lon=slon;st.price=price;st.routeKm=pnt.km;st.detourKm=detour;st.beforeDestination=pnt.km<=rd.firstLegKm;if(st.routeKm+detour/2.0>safeReach)continue;st.totalCost=litersNeeded*price+detour*cons/100.0*price;Station old=all.get(st.id);if(old==null||st.totalCost<old.totalCost)all.put(st.id,st);}}Station best=null;for(Station st:all.values())if(best==null||st.totalCost<best.totalCost)best=st;if(best==null)throw new Exception("Keine Tankstelle innerhalb der sicheren Restreichweite gefunden.");bestStation=best;final Station bs=best;final double need=litersNeeded;runOnUiThread(()->{resultText.setText(String.format(Locale.GERMANY,"✅ Empfehlung\n%s\n%s\nDiesel: %.3f €/l\nStreckenposition: ca. %.0f km\nGeschätzter Umweg: %.1f km\nBenötigt: ca. %.1f l\nGeschätzte Kosten inkl. Umweg: %.2f €\n\nRundfahrt: ca. %.0f km\nTankpreise: E-Control",bs.name,bs.address,bs.price,bs.routeKm,bs.detourKm,need,bs.totalCost,rd.totalKm));mapsButton.setEnabled(true);});}catch(Exception e){runOnUiThread(()->resultText.setText("Fehler: "+e.getMessage()));}}).start();}
 private RouteData route(double a1,double o1,double a2,double o2,double a3,double o3)throws Exception{String u=String.format(Locale.US,"https://router.project-osrm.org/route/v1/driving/%.6f,%.6f;%.6f,%.6f;%.6f,%.6f?overview=full&geometries=geojson&steps=false",o1,a1,o2,a2,o3,a3);JSONObject root=new JSONObject(get(u,"TiguanTankPlaner/2.1"));JSONArray routes=root.getJSONArray("routes");if(routes.length()==0)throw new Exception("Keine Route gefunden.");JSONObject r=routes.getJSONObject(0);RouteData rd=new RouteData();rd.totalKm=r.getDouble("distance")/1000.0;rd.firstLegKm=r.getJSONArray("legs").getJSONObject(0).getDouble("distance")/1000.0;JSONArray c=r.getJSONObject("geometry").getJSONArray("coordinates");double km=0,pl=0,po=0;for(int i=0;i<c.length();i++){JSONArray q=c.getJSONArray(i);double lon=q.getDouble(0),lat=q.getDouble(1);if(i>0)km+=haversine(pl,po,lat,lon);rd.points.add(new Point(lat,lon,km));pl=lat;po=lon;}return rd;}
 private double[] geocode(String raw)throws Exception{String q=raw.trim();String[] tries=new String[]{q,q+", Österreich",q.replace("str.","straße").replace("Str.","Straße")+", Österreich"};for(String t:tries){String u="https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&addressdetails=1&accept-language=de&q="+enc(t);try{JSONArray a=new JSONArray(get(u,"TiguanTankPlaner/2.1 Android; contact=topdiveair@gmail.com"));if(a.length()>0){JSONObject o=a.getJSONObject(0);return new double[]{Double.parseDouble(o.getString("lat")),Double.parseDouble(o.getString("lon"))};}}catch(Exception ignored){}try{Thread.sleep(1100);}catch(InterruptedException ignored){}}throw new Exception("Adresse nicht gefunden: "+raw+". Bitte z. B. '3500 Krems an der Donau' oder 'Ringstraße 1, Krems' eingeben.");}
 private JSONArray econtrol(double lat,double lon)throws Exception{String u=String.format(Locale.US,"https://api.e-control.at/sprit/1.0/search/gas-stations/by-address?latitude=%.6f&longitude=%.6f&fuelType=DIE&includeClosed=false",lat,lon);return new JSONArray(get(u,"TiguanTankPlaner/2.1"));}
 private static String get(String url,String ua)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Accept-Language","de-AT,de;q=0.9");int code=c.getResponseCode();if(code<200||code>=300)throw new Exception("Online-Dienst antwortet mit "+code);BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream(),"UTF-8"));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line);br.close();return s.toString();}
 private static String address(JSONObject l){String a=l.optString("address","");String zip=l.optString("postalCode","");String city=l.optString("city","");return(a+", "+zip+" "+city).replaceAll("^, |, $","").trim();} private static double haversine(double a,double o,double b,double p){double R=6371,dLat=Math.toRadians(b-a),dLon=Math.toRadians(p-o);double x=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(b))*Math.sin(dLon/2)*Math.sin(dLon/2);return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
 private void openMaps(){try{String dest=destinationInput.getText().toString().trim(),origin=currentLocation==null?"":String.format(Locale.US,"%.6f,%.6f",currentLocation.getLatitude(),currentLocation.getLongitude()),wp;if(bestStation==null)wp=dest;else{String st=String.format(Locale.US,"%.6f,%.6f",bestStation.lat,bestStation.lon);wp=bestStation.beforeDestination?st+"|"+dest:dest+"|"+st;}String url="https://www.google.com/maps/dir/?api=1&travelmode=driving"+(origin.isEmpty()?"":"&origin="+enc(origin))+"&destination="+enc(HOME)+"&waypoints="+enc(wp);startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}} private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
}
